#!/usr/bin/env python3
import hashlib,json,re,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/research'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 rp=D/'dedup-exact-root-memory-verification-20261012.json';r=json.loads(rp.read_text());assert all(sha(k)==v for k,v in r['pins'].items());mp=D/'dedup-exact-root-memory-source-20261012.json';m=json.loads(mp.read_text());s=Path(m['snapshot']);assert all(sha(s/k)==v for k,v in m['file_hashes'].items());assert (s/'src/exact.rs').read_text().startswith((R/'crates/rrrah-dedup/src/exact.rs').read_text());old=Path(m['baseline_source']);assert sha(old)==m['baseline_source_sha256'];text=old.read_text();a=text.index('fn collect(');b=text.index('\n/// Scan file/directory roots',a);assert text[a:b].replace('fn collect(','fn collect_unbounded_control(',1)in(s/'src/exact.rs').read_text()
 rows=r['rows'];assert [x['mode']for x in rows]==['baseline','bounded'];assert rows[0]['command'][:-1]==rows[1]['command'][:-1];assert rows[0]['stdout']==rows[1]['stdout']=='cancelled=true issues=0 groups=0 files=0 bytes=0 roots=100000\n';assert all(x['returncode']==0 and int(re.search(r'(\d+)\s+maximum resident set size',x['stderr'])[1])==x['rss_bytes']for x in rows);assert r['rss_reduction_bytes']==rows[0]['rss_bytes']-rows[1]['rss_bytes']>0
 out=D/'dedup-exact-root-memory-audit-20261012.json';assert not out.exists();out.write_text(json.dumps({'status':'audited_same_cancel_result_lower_root_preparation_rss','baseline_rss_bytes':rows[0]['rss_bytes'],'bounded_rss_bytes':rows[1]['rss_bytes'],'rss_reduction_bytes':r['rss_reduction_bytes'],'pins':{str(p):sha(p)for p in [rp,mp,Path(__file__)]},'scope':'Single two-process originalfunction/currentfunction control with100000callerowned roots. Complete pre-fixcollect copied verbatim except name; currentexactproduction preserved as exact prefix of harness source. Samecancel outcome, nofileIO. RSS includes callerinputs. No full successful scan/hardbytecap/universalbenchmark/platform/corpus/500 qualification.'},indent=2)+'\n');print('Audited identical cancellation, root-preparation RSS',rows[0]['rss_bytes'],'->',rows[1]['rss_bytes'])
if __name__=='__main__':main()
